"""Standalone visual comparison for fixed-rate metric scenarios."""
import json
from pathlib import Path
import sys

HTML = '''<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Metrics scenario benchmarks</title>
<style>*{box-sizing:border-box}body{background:#101010;color:#ddd;font:16px system-ui;margin:0;padding:32px}main{max-width:1700px;margin:auto;padding:36px;background:#202020;border:1px solid #383838;border-radius:20px}h1{margin:12px 0}p,small{color:#aaa}select{background:#303030;color:white;padding:12px;border:1px solid #555;border-radius:8px;font:inherit}.legend{display:flex;gap:32px;margin:28px 0}.dot{display:inline-block;width:14px;height:14px;border-radius:3px;margin-right:8px}svg{width:100%;height:auto}table{width:100%;border-collapse:collapse;font-size:14px}td,th{text-align:left;padding:12px;border-bottom:1px solid #393939}a{color:#bbb}.note{line-height:1.6;background:#292929;padding:18px;border-radius:8px}</style>
<main><small>LOCAL PREVIEW · METRICS · RUST GENERATOR</small><h1>Pipeline Performance Benchmarks</h1><p>10,000 requests/sec × 512 points/request = 5.12 million points/sec · OTLP/gRPC input</p>
<select id="run" aria-label="Benchmark iteration"></select> <select id="view"><option value="efficiency">Points/sec per core</option><option value="cpu">CPU cores</option><option value="rate">Points/sec reached</option></select>
<div class="legend" id="legend"><span><i class="dot" style="background:#00cc66"></i>Edge Delta (Rust) · PR #20</span><span><i class="dot" style="background:#a348ff"></i>OpenTelemetry Collector · 0.162.0</span><span><i class="dot" style="background:#f04444"></i>Bindplane (Dynatrace) · 1.110.1</span></div><p id="caption"></p><svg id="chart" viewBox="0 0 1500 510"></svg><p class="note"><span id="duration">30 seconds of input per trial</span>, followed by delivery drain. CPU cost includes processing through the final flush, normalized to the input window. Dashed bars fell short of the offered load. N/A means operation or delivery verification failed; it is not a capability claim. Aggregation and rollup use native processing and flush behavior.</p><p id="configNote"></p><table><thead><tr><th>Scenario</th><th>Vendor</th><th>Requests/sec</th><th>CPU cost</th><th>Output points</th><th>Verification</th><th>Status</th></tr></thead><tbody id="rows"></tbody></table><p>64 recurring resource groups × 64 host series. 64 input connections, up to 1,024 in-flight requests. Isolated c8i.8xlarge load, agent, and sink hosts. <span id="trials">One trial per case.</span> <a href="results.json">Download results</a></p></main>
<script>const report=__DATA__;const runs=report.runs||[{name:'Current',...report}];let data=runs[runs.length-1];const scenarioOrder=['pass-through','filter','enrich','aggregate','rollup','combined'];const vendorOrder=['red','otelcol','bindplane'];const names={red:'Edge Delta (Rust)',otelcol:'OpenTelemetry Collector',bindplane:'Bindplane (Dynatrace)'};const colors={red:'#00cc66',otelcol:'#a348ff',bindplane:'#f04444'};const fmt=n=>new Intl.NumberFormat('en-US',{notation:n>=10000?'compact':'standard',maximumFractionDigits:2}).format(n);
const cost=r=>r.through_delivery.cpu_seconds/r.input_window.elapsed_seconds;
function render(){document.getElementById('configNote').textContent=data.note||'';const scenarios=scenarioOrder.filter(s=>data.rows.some(r=>r.scenario===s));const vendors=vendorOrder.filter(v=>data.rows.some(r=>r.vendor===v));document.getElementById('legend').innerHTML=vendors.map(v=>`<span><i class="dot" style="background:${colors[v]}"></i>${names[v]} · ${v==='red'?(data.red_label||'PR #20'):v==='otelcol'?'0.162.0':'1.110.1'}</span>`).join('');document.getElementById('duration').textContent=`${data.seconds||30} seconds of input per trial`;document.getElementById('trials').textContent='Every measured trial is listed below; bars show medians across trials.';const view=document.getElementById('view').value;const valid=r=>r&&r.load&&r.delivery_verified&&r.operation_verified;const value=r=>!valid(r)?0:view==='cpu'?cost(r):view==='rate'?r.load.achieved_rps*512:r.load.achieved_rps*512/cost(r);const median=xs=>{xs.sort((a,b)=>a-b);return (xs[Math.floor((xs.length-1)/2)]+xs[Math.floor(xs.length/2)])/2};const max=Math.max(1,...data.rows.map(value))*1.18;let svg='';for(let i=0;i<5;i++){let y=420-i*90;svg+=`<line x1="85" x2="1490" y1="${y}" y2="${y}" stroke="#393939"/><text x="72" y="${y+5}" text-anchor="end" fill="#aaa">${fmt(max*i/4)}</text>`}
scenarios.forEach((scenario,i)=>{const group=1380/scenarios.length;const base=100+i*group+(group-vendors.length*60)/2;vendors.forEach((v,j)=>{const rows=data.rows.filter(r=>r.scenario===scenario&&r.vendor===v),r=rows[0],verified=rows.length>0&&rows.every(valid),n=verified?median(rows.map(value)):0,h=n/max*360,x=base+j*60,solid=rows.every(r=>r.status==='measured');svg+=`<rect x="${x}" y="${420-h}" width="48" height="${h}" rx="4" fill="${colors[v]}" fill-opacity="${solid?1:.25}" stroke="${colors[v]}" ${solid?'':'stroke-dasharray="5 4"'}/><text x="${x+24}" y="${405-h}" text-anchor="middle" fill="#ccc" font-size="12">${verified?fmt(n):'N/A'}</text>`});svg+=`<text x="${base+(vendors.length-1)*30+24}" y="465" text-anchor="middle" fill="#ddd">${scenario==='pass-through'?'Pass-Through':scenario[0].toUpperCase()+scenario.slice(1)}</text>`});document.getElementById('chart').innerHTML=svg;document.getElementById('caption').textContent=view==='cpu'?'CPU seconds per input-window second · lower is better':view==='rate'?'Input points/sec reached · higher is better':'Input points/sec per CPU core · higher is better';document.getElementById('rows').innerHTML=data.rows.map(r=>`<tr><td>${r.scenario}</td><td>${names[r.vendor]}</td><td>${r.load?fmt(r.load.achieved_rps):'—'}</td><td>${r.load?cost(r).toFixed(3):'—'}</td><td>${r.delivered?fmt(r.delivered.points):'—'}</td><td>${valid(r)?'Verified':'Not verified'}</td><td>${r.status.replaceAll('_',' ')}</td></tr>`).join('')};const chooser=document.getElementById('run');runs.forEach((r,i)=>{const o=document.createElement('option');o.value=i;o.textContent=r.name;chooser.appendChild(o)});chooser.value=runs.length-1;chooser.onchange=()=>{data=runs[Number(chooser.value)];render()};document.getElementById('view').onchange=render;render();</script>'''


def main():
    data=json.loads(Path(sys.argv[1]).read_text())
    out=Path(sys.argv[2]);out.parent.mkdir(parents=True,exist_ok=True)
    out.write_text(HTML.replace('__DATA__',json.dumps(data).replace('<','\\u003c')))


if __name__=='__main__':main()
